// Fixed local-wall expectations, not generated by the formatter under test.
var formatCivilInstants = []string{"2024-11-03T05:30:00Z", "2024-11-03T06:30:00Z", "1969-12-31T23:59:59.999999999Z", "2024-01-01T05:00:00.123456789Z", "2024-03-10T06:59:59Z", "2024-03-10T07:00:00Z"}
var formatCivilTexts = []string{"2024-11-03T01:30:00.000000000", "2024-11-03T01:30:00.000000000", "1969-12-31T18:59:59.999999999", "2024-01-01T00:00:00.123456789", "2024-03-10T01:59:59.000000000", "2024-03-10T03:00:00.000000000"}

func formatCivilZone(t *testing.T, name string) expr.TimeZone {
	t.Helper()
	encoded, e := os.ReadFile(filepath.Join("..", "expr", "testdata", "timezone", name+".tzif.b64"))
	if e != nil {
		t.Fatal(e)
	}
	data, e := base64.StdEncoding.DecodeString(strings.TrimSpace(string(encoded)))
	if e != nil {
		t.Fatal(e)
	}
	z, e := expr.TimeZoneFromTZData(name, data)
	if e != nil {
		t.Fatal(e)
	}
	clear(data)
	return z
}
func formatCivilNS(t *testing.T, text string) int64 {
	t.Helper()
	v, e := time.Parse(time.RFC3339, text)
	if e != nil {
		t.Fatal(e)
	}
	return v.UnixNano()
}
func formatCivilQuery(t *testing.T, s *Session, n int) LazyFrame {
	t.Helper()
	rb := array.NewRecordBuilder(am.DefaultAllocator, arrow.NewSchema([]arrow.Field{{Name: "id", Type: arrow.PrimitiveTypes.Int64}, {Name: "ts", Type: &arrow.TimestampType{Unit: arrow.Nanosecond, TimeZone: "UTC"}, Nullable: true}}, nil))
	for i := 0; i < n; i++ {
		rb.Field(0).(*array.Int64Builder).Append(int64(i))
		b := rb.Field(1).(*array.TimestampBuilder)
		if i%7 == 0 {
			b.AppendNull()
		} else {
			b.Append(arrow.Timestamp(formatCivilNS(t, formatCivilInstants[i%6])))
		}
	}
	rec := rb.NewRecordBatch()
	rb.Release()
	var chunks []arrow.RecordBatch
	for start := 0; start < n; start += 65 {
		chunks = append(chunks, rec.NewSlice(int64(start), int64(min(start+65, n))))
	}
	q, e := s.ScanArrow(chunks...)
	for _, c := range chunks {
		c.Release()
	}
	rec.Release()
	if e != nil {
		t.Fatal(e)
	}
	z := formatCivilZone(t, "new_york")
	return q.WithColumns(FormatCivilTimestamp(Col("ts"), z).Alias("text"))
}
func formatCivilRows(n int) []int {
	r := make([]int, n)
	for i := range r {
		r[i] = i
	}
	return r
}

func formatCivilWant(t *testing.T, row int, name string) any {
	if name == "id" {
		return int64(row)
	}
	if row%7 == 0 {
		return nil
	}
	if name == "ts" {
		return formatCivilNS(t, formatCivilInstants[row%6])
	}
	if name == "text" {
		return formatCivilTexts[row%6]
	}
	t.Fatal("unknown column", name)
	return nil
}
func formatCivilCheck(t *testing.T, df DataFrame, rows []int) {
	t.Helper()
	for _, name := range []string{"id", "ts", "text"} {
		c, e := df.Column(name)
		if e != nil {
			t.Fatal(e)
		}
		expectedType := memory.TypeInt64
		if name == "ts" {
			expectedType = memory.TypeTimestamp
		}
		if name == "text" {
			expectedType = memory.TypeString
		}
		if c.Type() != expectedType {
			t.Fatal("logical type", name, c.Type())
		}
		got, e := c.ToAnySlice()
		if e != nil {
			t.Fatal(e)
		}
		want := make([]any, len(rows))
		for i, row := range rows {
			want[i] = formatCivilWant(t, row, name)
		}
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("%s got %v want %v", name, got, want)
		}
	}
}
func TestFormatCivilLazyTransport(t *testing.T) {
	s := NewSession(engine.DefaultOptions())
	defer s.Close()
	q := formatCivilQuery(t, s, 65)
	rows := formatCivilRows(65)
	df, e := q.Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	defer df.Close()
	formatCivilCheck(t, df, rows)
	selected, e := q.Filter(expr.GT(Col("id"), expr.I64(31))).Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	defer selected.Close()
	formatCivilCheck(t, selected, rows[32:])
	path := filepath.Join(t.TempDir(), "civil-format.arrow")
	if _, e = q.SinkIPC(context.Background(), path, IPCSinkOptions{}); e != nil {
		t.Fatal(e)
	}
	f, e := os.Open(path)
	if e != nil {
		t.Fatal(e)
	}
	rd, e := ipc.NewFileReader(f)
	if e != nil {
		f.Close()
		t.Fatal(e)
	}
	var recs []arrow.RecordBatch
	for i := 0; i < rd.NumRecords(); i++ {
		r, e := rd.RecordBatchAt(i)
		if e != nil {
			t.Fatal(e)
		}
		for _, field := range r.Schema().Fields() {
			if field.Name == "text" && (field.Type.ID() != arrow.STRING || !field.Nullable) {
				t.Fatal("IPC String metadata", field)
			}
		}
		recs = append(recs, r)
	}
	iq, e := s.ScanArrow(recs...)
	for _, r := range recs {
		r.Release()
	}
	rd.Close()
	f.Close()
	if e != nil {
		t.Fatal(e)
	}
	idf, e := iq.Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	defer idf.Close()
	formatCivilCheck(t, idf, rows)
	pp := filepath.Join(t.TempDir(), "civil-format.parquet")
	result, e := q.SinkParquet(context.Background(), pp, ParquetSinkOptions{RowGroupRows: 17})
	if e != nil {
		t.Fatal(e)
	}
	pq, e := s.ScanParquet(result.Files[0])
	if e != nil {
		t.Fatal(e)
	}
	pdf, e := pq.Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	defer pdf.Close()
	formatCivilCheck(t, pdf, rows)
	// Independent Arrow Parquet reader verifies both String metadata and each stored value.
	pr, e := file.OpenParquetFile(pp, false)
	if e != nil {
		t.Fatal(e)
	}
	ar, e := pqarrow.NewFileReader(pr, pqarrow.ArrowReadProperties{}, am.DefaultAllocator)
	if e != nil {
		pr.Close()
		t.Fatal(e)
	}
	table, e := ar.ReadTable(context.Background())
	if e != nil {
		pr.Close()
		t.Fatal(e)
	}
	for i, field := range table.Schema().Fields() {
		if field.Name != "text" {
			continue
		}
		if field.Type.ID() != arrow.STRING || !field.Nullable {
			t.Fatal("Parquet String metadata", field)
		}
		var got []any
		for _, ch := range table.Column(i).Data().Chunks() {
			v, ok := ch.(*array.String)
			if !ok {
				t.Fatal("Parquet string array", ch.DataType())
			}
			for j := 0; j < v.Len(); j++ {
				if v.IsNull(j) {
					got = append(got, nil)
				} else {
					got = append(got, v.Value(j))
				}
			}
		}
		want := make([]any, len(rows))
		for j, row := range rows {
			want[j] = formatCivilWant(t, row, "text")
		}
		if !reflect.DeepEqual(got, want) {
			t.Fatal("independent Parquet text oracle")
		}
	}
	table.Release()
	pr.Close()
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	cd, ce := q.Collect(ctx)
	if ce == nil {
		cd.Close()
	}
	if !errors.Is(ce, context.Canceled) {
		t.Fatal("cancel", ce)
	}
	s.Close()
	formatCivilCheck(t, df, rows)
	formatCivilCheck(t, idf, rows)
	formatCivilCheck(t, pdf, rows)
	df.Close()
	idf.Close()
	pdf.Close()
	selected.Close()
	if s.Engine().Memory().Used() != 0 {
		t.Fatal("owned leak")
	}
	opts := engine.DefaultOptions()
	opts.MemoryLimitBytes = 1
	tiny := NewSession(opts)
	tq := formatCivilQuery(t, tiny, 65)
	td, te := tq.Collect(context.Background())
	if te == nil {
		td.Close()
	}
	tiny.Close()
	if !errors.Is(te, memory.ErrBudgetExceeded) || tiny.Engine().Memory().Used() != 0 {
		t.Fatal("budget", te)
	}
}
func TestFormatCivilLazyInMemoryAndFold(t *testing.T) {
	b := memory.NewBatch()
	b.Rows = 4
	b.Int64s["ts"] = &memory.Int64Vector{Values: []int64{formatCivilNS(t, formatCivilInstants[0]), formatCivilNS(t, formatCivilInstants[1]), formatCivilNS(t, formatCivilInstants[3]), 0}, Validity: memory.Bitmap{7}}
	b.Int64s["id"] = &memory.Int64Vector{Values: []int64{0, 1, 2, 3}}
	src, e := inmemory.New(memory.NewSchema(memory.Field{Name: "ts", Type: memory.TypeTimestamp, Nullable: true}, memory.Field{Name: "id", Type: memory.TypeInt64}), b)
	if e != nil {
		t.Fatal(e)
	}
	s := NewSession(engine.DefaultOptions())
	defer s.Close()
	z := formatCivilZone(t, "new_york")
	q := s.FromSource(src).WithColumns(FormatCivilTimestamp(Col("ts"), z).Alias("text"))
	df, e := q.Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	defer df.Close()
	c, e := df.Column("text")
	if e != nil {
		t.Fatal(e)
	}
	got, e := c.ToAnySlice()
	if e != nil {
		t.Fatal(e)
	}
	if !reflect.DeepEqual(got, []any{formatCivilTexts[0], formatCivilTexts[1], formatCivilTexts[3], nil}) {
		t.Fatal("fold text", got)
	}
	// Formatting two fold instants intentionally yields identical text. Parsing requires an explicit policy.
	for _, policy := range []expr.CivilFoldPolicy{expr.FoldReject, expr.FoldEarlier, expr.FoldLater} {
		r, e := expr.NewCivilTimeResolver(context.Background(), z, expr.CivilResolveOptions{Fold: policy, Gap: expr.GapReject})
		if e != nil {
			t.Fatal(e)
		}
		pd, pe := q.WithColumns(ParseCivilTimestamp(Col("text"), r).Alias("parsed")).Collect(context.Background())
		if policy == expr.FoldReject {
			if pe == nil {
				pd.Close()
			}
			if !errors.Is(pe, expr.ErrCivilFold) {
				t.Fatal("fold reject", pe)
			}
			continue
		}
		if pe != nil {
			t.Fatal(pe)
		}
		pc, e := pd.Column("parsed")
		if e != nil {
			t.Fatal(e)
		}
		pv, e := pc.ToAnySlice()
		if e != nil {
			t.Fatal(e)
		}
		index := 0
		if policy == expr.FoldLater {
			index = 1
		}
		want := []any{formatCivilNS(t, formatCivilInstants[index]), formatCivilNS(t, formatCivilInstants[index]), formatCivilNS(t, formatCivilInstants[3]), nil}
		if !reflect.DeepEqual(pv, want) {
			t.Fatal("explicit fold choice or unique roundtrip", pv, want)
		}
		pd.Close()
	}
	guard, e := s.FromSource(src).SelectExprs(expr.If(expr.GT(Col("id"), expr.I64(1)), FormatCivilTimestamp(Col("ts"), z), expr.Str("inactive")).Alias("guard")).Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	gc, e := guard.Column("guard")
	if e != nil {
		t.Fatal(e)
	}
	gv, e := gc.ToAnySlice()
	if e != nil {
		t.Fatal(e)
	}
	if !reflect.DeepEqual(gv, []any{"inactive", "inactive", formatCivilTexts[3], nil}) {
		t.Fatal("guard", gv)
	}
	guard.Close()
	s.Close()
	c, e = df.Column("text")
	if e != nil {
		t.Fatal(e)
	}
	got, e = c.ToAnySlice()
	if e != nil || !reflect.DeepEqual(got, []any{formatCivilTexts[0], formatCivilTexts[1], formatCivilTexts[3], nil}) {
		t.Fatal("owned string after source close", got, e)
	}
	df.Close()
	if s.Engine().Memory().Used() != 0 {
		t.Fatal("inmemory owner leak")
	}
}
func TestFormatCivilLazyHistoricalSeconds(t *testing.T) {
	b := memory.NewBatch()
	b.Rows = 1
	b.Int64s["ts"] = &memory.Int64Vector{Values: []int64{formatCivilNS(t, "1900-01-01T00:00:00.000000001Z")}}
	src, e := inmemory.New(memory.NewSchema(memory.Field{Name: "ts", Type: memory.TypeTimestamp}), b)
	if e != nil {
		t.Fatal(e)
	}
	s := NewSession(engine.DefaultOptions())
	defer s.Close()
	df, e := s.FromSource(src).SelectExprs(FormatCivilTimestamp(Col("ts"), formatCivilZone(t, "paris")).Alias("text")).Collect(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	defer df.Close()
	c, e := df.Column("text")
	if e != nil {
		t.Fatal(e)
	}
	got, e := c.ToAnySlice()
	if e != nil || !reflect.DeepEqual(got, []any{"1900-01-01T00:09:21.000000001"}) {
		t.Fatal("historical second offset", got, e)
	}
	df.Close()
	s.Close()
	if s.Engine().Memory().Used() != 0 {
		t.Fatal("historical owner leak")
	}
}
func TestFormatCivilLazyActualSpill(t *testing.T) {
	opts := engine.DefaultOptions()
	opts.PreparedCacheBytes = 0
	opts.ExecutionPolicy = engine.ExecutionBounded
	opts.MemoryLimitBytes = 8 << 20
	dir := t.TempDir()
	opts.Spill = engine.SpillOptions{Directory: dir, MaxBytes: 64 << 20}
	s := NewSession(opts)
	defer s.Close()
	q := formatCivilQuery(t, s, 260)
	budget, e := s.Engine().BeginQueryMemory()
	if e != nil {
		t.Fatal(e)
	}
	defer budget.Close()
	observer := &formatCivilRunContext{Context: memory.WithQueryBudget(context.Background(), budget), dir: dir}
	done, stopped := make(chan struct{}), make(chan struct{})
	go func() {
		defer close(stopped)
		for {
			select {
			case <-done:
				return
			default:
				observer.Err()
				runtime.Gosched()
			}
		}
	}()
	df, e := q.Sort(AscNullsFirst("text"), Asc("id")).Collect(observer)
	close(done)
	<-stopped
	if e != nil {
		t.Fatal(e)
	}
	defer df.Close()
	if budget.Snapshot().SpilledBytes <= 0 || observer.maxRuns < 2 {
		t.Fatal("expected actual runs", budget.Snapshot(), observer.maxRuns)
	}
	t.Logf("civil format spill bytes=%d runs=%d", budget.Snapshot().SpilledBytes, observer.maxRuns)
	rows := formatCivilRows(260)
	sort.Slice(rows, func(i, j int) bool {
		a, b := rows[i], rows[j]
		if a%7 == 0 || b%7 == 0 {
			if a%7 == 0 && b%7 == 0 {
				return a < b
			}
			return a%7 == 0
		}
		x, y := formatCivilTexts[a%6], formatCivilTexts[b%6]
		if x == y {
			return a < b
		}
		return x < y
	})
	formatCivilCheck(t, df, rows)
	budget.Close()
	s.Close()
	e = filepath.WalkDir(dir, func(path string, d fs.DirEntry, e error) error {
		if e != nil {
			return e
		}
		if !d.IsDir() {
			t.Errorf("retained spill file %s", path)
		}
		return nil
	})
	if e != nil {
		t.Fatal(e)
	}
	formatCivilCheck(t, df, rows)
	df.Close()
	if s.Engine().Memory().Used() != 0 {
		t.Fatal("spill owner leak")
	}
}

type formatCivilRunContext struct {
	context.Context
	mu      sync.Mutex
	dir     string
	maxRuns int
}

func (c *formatCivilRunContext) Err() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	n := 0
	_ = filepath.WalkDir(c.dir, func(_ string, d fs.DirEntry, e error) error {
		if e == nil && !d.IsDir() {
			info, e := d.Info()
			if e == nil && info.Size() > 0 {
				n++
			}
		}
		return nil
	})
	if n > c.maxRuns {
		c.maxRuns = n
	}
	return c.Context.Err()
}
